/**
 * Queries the dictionary module across optimized prefix maps using NLP Lemmatization.
 * @param {string} spanishWord
 * @returns {string|null}
 */
function getTranslation(spanishWord) {
  if (!spanishWord) return null;
  
  let cleanWord = spanishWord.trim().toLowerCase();
  if (typeof esCompromise === 'function') {
    try {
      const doc = esCompromise(cleanWord);
      doc.compute('root');
      const data = doc.json();
      if (data && data.length > 0 && data.terms && data.terms.length > 0) {
        cleanWord = data.terms[0].root || data.terms[0].text.toLowerCase();
      }
    } catch(e) {}
  }
  
  cleanWord = cleanWord.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  
  const prefix = cleanWord.length >= 2 ? cleanWord.substring(0, 2) : cleanWord;
  const safePrefix = prefix.replace(/[^a-zA-Z0-9]/g, '_');
  
  const targetMap = masterDictionaryRegistry[safePrefix];
  if (targetMap && targetMap.has(cleanWord)) {
    return targetMap.get(cleanWord);
  }
  return null;
}

